<script>
import { mapState, mapActions } from 'vuex';
import ApiService from '../services/api';
import LocationService from '../services/location';
import NotificationService from '../services/notification';

export default {
  name: 'DriverHomeView',
  data() {
    return {
      completedCount: 0,
      ongoingCount: 0,
      pendingCount: 0,
      weeklyEarnings: 0,
      loading: true,
      togglingStatus: false,
    };
  },
  computed: {
    ...mapState('auth', ['user']),
    firstName() {
      const n = (this.user && this.user.name) || 'Driver';
      return String(n).split(/\s+/)[0];
    },
  },
  mounted() {
    // get fcm from the device
    Android.getFcmToken();

    window.onFcmTokenReceived = function (token) {
      try {
        const response =  ApiService.put(
            `/driver/fcm-token`,
            {
              fcm_token: token,
            }
        );

        if (response.success !== false) {
         // alert('FCM sent!');
        } else {
          alert('Failed to update fcm');
        }
      } catch (error) {
        alert('Failed to update fcm');
      } finally {

      }
    };

    window.onFcmTokenError = function (message) {
      alert('Unable to get FCM token');
    };


    this.fetchOrderCounts();
    NotificationService.registerTokenWithBackend().catch((err) => {
      console.warn('FCM token sync failed:', err);
    });
  },
  methods: {
    ...mapActions('auth', ['toggleOnlineStatus']),
    goPending() {
      this.$router.push({ name: 'PendingOrders' });
    },
    goOngoing() {
      this.$router.push({ name: 'OngoingOrders' });
    },

    async fetchOrderCounts() {
      try {
        const response = await ApiService.get('/driver/deliveries');

        let deliveriesList = [];

        if (response.success) {
          if (response.deliveries) {
            deliveriesList = response.deliveries;
          } else if (response.data && response.data.deliveries) {
            deliveriesList = response.data.deliveries;
          } else if (Array.isArray(response.data)) {
            deliveriesList = response.data;
          } else if (Array.isArray(response)) {
            deliveriesList = response;
          }

          const now = new Date();
          const dayOfWeek = now.getDay();
          const diff = now.getDate() - dayOfWeek + (dayOfWeek === 0 ? -6 : 1);
          const weekStart = new Date(now.setDate(diff));
          weekStart.setHours(0, 0, 0, 0);

          const completed = deliveriesList.filter(
            (d) => d.status === 'completed'
          );

          const ongoing = deliveriesList.filter(
            (d) =>
              d.status === 'assigned' ||
              d.status === 'picking_up' ||
              d.status === 'in_progress'
          );

          const pending = deliveriesList.filter((d) => d.status === 'pending');

          const completedThisWeek = completed.filter((delivery) => {
            const completedDate = new Date(
              delivery.updated_at || delivery.created_at
            );
            return completedDate >= weekStart;
          });

          const earnings = completedThisWeek.reduce((total, delivery) => {
            const price =
              typeof delivery.delivery_price === 'string'
                ? parseFloat(delivery.delivery_price)
                : delivery.delivery_price;
            return total + (price || 0);
          }, 0);

          this.completedCount = completed.length;
          this.ongoingCount = ongoing.length;
          this.pendingCount = pending.length;
          this.weeklyEarnings = earnings;
        }
      } catch (error) {
        console.error('Error fetching order counts:', error);
      } finally {
        this.loading = false;
      }
    },
    async handleToggleOnlineStatus() {
      try {
        this.togglingStatus = true;

        if (!this.user.isOnline) {
          const location = await LocationService.getCurrentLocation();

          if (!location) {
            window.alert(
              'Unable to get your location. Please:\n\n1. Enable location services on your device\n2. Grant location permission to this app\n3. Make sure location is turned on in device settings'
            );
            this.togglingStatus = false;
            return;
          }

          await this.toggleOnlineStatus({
            latitude: location.latitude,
            longitude: location.longitude,
          });
        } else {
          await this.toggleOnlineStatus({});
        }
      } catch (error) {
        window.alert(error.message || 'Failed to toggle online status');
      } finally {
        this.togglingStatus = false;
      }
    },
  },
};
</script>

